mapper.select:
select annual_leave_id, emp_id, leave_year, granted_days, used_days
from annual_leave
where emp_id = #{empId}
  and leave_year = #{leaveYear}

mapper.update:
update annual_leave
set used_days = used_days + #{days}
where emp_id = #{empId}
  and leave_year = #{leaveYear}
  and granted_days - used_days >= #{days}
